const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.building}"/></svg>`;
const button=(label,action,help,cls='secondary',extra='')=>`<button class="${cls}" data-action="${action}" title="${e(help)}" ${extra.includes('type=')?'':'type="button"'} ${extra}>${label}</button>`;
const select=(name,label,options,value='',extra='')=>`<label class="field"><span>${label}</span><select name="${name}" ${extra}>${options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${e(v)}" ${String(value)===String(v)?'selected':''}>${e(t)}</option>`;}).join('')}</select></label>`;
const input=(name,label,value='',type='number',extra='')=>`<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${e(value??'')}" ${type==='number'?'min="0" step="any"':''} ${extra}></label>`;
const date=v=>v?new Intl.DateTimeFormat('es-PE',{dateStyle:'medium',timeStyle:'short',timeZone:'America/Lima'}).format(new Date(v)):'Sin fecha';
const PAW_API_BASE=(window.PAW_CONFIG?.apiBase || '').replace(/\/+$/, '');
let backendStorage='desconocida';
let token='', online=false, real=[],sources=[],runs=[],mode='real',view='analizar',pendingImport=null,pollTimer;
let state={settings:structuredClone(DEFAULT_SETTINGS),saved:[],notes:{}};
let localItems=[];
try{const saved=JSON.parse(localStorage.getItem('paw-local-v1')||'null');if(Array.isArray(saved))localItems=saved.filter(o=>o.id&&o.title&&o.captured_at); }catch{}
const filters={};let sort='score';let activeId=null;
const items=()=>mode==='demo'?DEMO:mode==='manual'?localItems:real;
const selected=()=>sortOpportunities(filterOpportunities(items(),filters,state.settings),sort,state.settings);
const metric=(label,value,description,ico)=>`<article class="metric"><div>${label}${icon(ico)}</div><strong>${value}</strong><small>${description}</small></article>`;

async function api(path,body){
  if (!PAW_API_BASE && location.hostname.endsWith('.github.io')) {
    throw new Error('API no configurada: primero habilita Cloudflare y establece PAW_CONFIG.apiBase en config.js.');
  }
  const remote=Boolean(PAW_API_BASE);
  const url=remote ? PAW_API_BASE+'/api/'+path : './api/'+path;
  const headers=body ? {'Content-Type':'application/json'} : {};
  if (body && !remote && token) headers['X-PAW-Token']=token;
  const r=await fetch(url,{method:body?'POST':'GET',headers,
    credentials:remote?'include':'same-origin',body:body?JSON.stringify(body):undefined});
  if(!r.ok){let detail;try{detail=(await r.json()).detail}catch{}throw new Error(typeof detail==='string'?detail:`Error ${r.status}: verifica los campos y el servicio local.`);}
  return r.json();
}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),5500);}
async function persist(){if(online)await api('state',state);else localStorage.setItem('paw-settings-v1',JSON.stringify(state));}
function saveLocal(){localStorage.setItem('paw-local-v1',JSON.stringify(localItems));}
function download(name,text,type='text/csv'){const a=document.createElement('a');const url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function workflow(active){return `<ol class="workflow" aria-label="Flujo de inversión">${['Captar','Analizar','Revisar','Decidir'].map((name,i)=>`<li ${active===i+1?'aria-current="step"':''}><span>${i+1}</span>${name}${i<3?icon('chevron'):''}</li>`).join('')}</ol>`;}
function city(){return `<svg class="city" viewBox="0 0 460 200" fill="none" aria-hidden="true"><g stroke="currentColor" stroke-width="1"><path d="m20 165 180-72 250 90M90 190l180-75M180 200l150-60M20 140l240 60M55 114l280 86" opacity=".24"/><path d="m70 153 0-60 52-21 0 62-52 19 35 15 53-21V85l-36-13M105 168V107l53-22M70 93l35 14M178 136V44l52-22 0 94-52 20 35 15 53-22V36l-36-14M213 151V58l53-22M178 44l35 14M286 159V89l48-20v70l-48 20 33 14 49-21V82l-34-13M319 173v-70l49-21M286 89l33 14"/><path d="m78 104 18 7m-18 7 18 7m-18 7 18 7m17-25 35-14m-35 28 35-14m-35 28 35-14M186 56l18 7m-18 7 18 7m-18 7 18 7m-18 7 18 7m-18 7 18 7m17-47 35-14m-35 28 35-14m-35 28 35-14m-35 28 35-14m-35 28 35-14m38-8 18 7m-18 7 18 7m-18 7 18 7m17-25 32-13m-32 27 32-13m-32 27 32-13" opacity=".6"/></g><circle cx="371" cy="38" r="19" stroke="currentColor" opacity=".45"/><path d="m364 38 5 5 9-10" stroke="currentColor" stroke-width="2"/></svg>`;}
function shell(){
  const labels={captar:'Captar oportunidades',analizar:'Analizar oportunidades',expedientes:'Expedientes',configuracion:'Configuración'};
  $('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#analizar"><img src="./assets/mark.svg" alt="" width="40" height="40"><span>SILJASA4H<small>HOLDING EMPRESARIAL</small></span></a><div class="workspace-label">WORKSPACE <span>01</span></div><p class="side-caption">INVERSIÓN INMOBILIARIA</p><nav>${[['captar','radar'],['analizar','chart'],['expedientes','folder'],['configuracion','settings']].map(([id,ico])=>`<a href="#${id}" class="nav-link ${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(ico)}${labels[id]}${id==='expedientes'?`<span class="nav-count">${state.saved.length}</span>`:''}</a>`).join('')}</nav><div class="side-bottom"><div class="capital-card"><span>CAPITAL DE REFERENCIA</span><strong>${money(state.settings.budget)}</strong><small>Editable · no limita la captación</small><a href="#configuracion">Ajustar presupuesto ${icon('arrow')}</a></div><div class="local-status"><span class="status-dot"></span>${online?'API conectada':'Vista estática'}<small>${online?'Base de datos privada · '+e(backendStorage):'Conecta la API privada para captar'}</small></div><div class="profile"><span class="avatar">P</span><div>SILJASA4H<small>Espacio local · un usuario</small></div></div></div></aside><div class="main-shell"><header class="topbar"><div><span class="breadcrumb">SILJASA4H</span><span class="slash">/</span>${labels[view]}</div><span class="top-right">${icon('globe')} Perú <span class="separator">|</span> USD / PEN <span class="avatar light">P</span></span></header><main id="main"><div class="page-top"><div class="eyebrow">PAW / INVERSIÓN INMOBILIARIA</div><div class="page-title"><h1>${view==='analizar'?'Radar de oportunidades':labels[view]}</h1><span class="environment">${mode==='demo'?'DEMO — NO REAL':mode==='manual'?'CARGA COMPLEMENTARIA':'DATOS DE FUENTES PÚBLICAS'}</span></div><p class="intro">Descubre inmuebles, contrasta la evidencia y evalúa cada inversión con criterio.</p></div><div class="scope-note">${icon('shield')} ${online?'Los datos se almacenan en el servidor privado.':'La captación necesita conexión autenticada al backend.'} Ninguna acción compra inmuebles ni presenta ofertas.</div>${workflow(view==='captar'?1:view==='analizar'?2:view==='expedientes'?3:4)}<div id="content"></div><footer class="page-footer"><span>SILJASA4H <b>·</b> PAW Radar Inmobiliario</span><span>Información para evaluar. Decisiones siempre humanas.</span><span>LOCAL / v1.0</span></footer></main></div>`;
  renderView();
}
function renderView(){if(view==='analizar')renderAnalysis();else if(view==='captar')renderCapture();else if(view==='expedientes')renderDossiers();else renderSettings();}
function renderAnalysis(){
  const all=items(),ready=all.filter(o=>financials(o,state.settings).ready),eligible=ready.filter(o=>financials(o,state.settings).total<=state.settings.budget),unverified=all.filter(o=>!CHECKS.every(c=>o.checks?.includes(c)));
  $('#content').innerHTML=`<section class="hero"><div><div class="hero-kicker"><span class="status-dot"></span> TU PRÓXIMA INVERSIÓN, EN PERSPECTIVA</div><h2>Más información.<br><em>Mejores decisiones.</em></h2><p>Todo el mercado encontrado. Tú defines los filtros.</p><a href="#captar" class="hero-link">1. Explorar fuentes ${icon('arrow')}</a></div>${city()}<span class="hero-caption">PAW / INTELIGENCIA INMOBILIARIA</span></section><section class="metrics" aria-label="Resumen">${metric('Inmuebles captados',all.length,'Sin exclusiones por precio','building')}${metric('Dentro del presupuesto',eligible.length,`${ready.length} escenarios completos · referencia USD`,'chart')}${metric('En seguimiento',state.saved.filter(id=>all.some(o=>o.id===id)).length,'Tu selección de oportunidades','bookmark')}${metric('Requieren verificación',unverified.length,'Diligencia legal y financiera','shield')}</section><section class="results-panel"><div class="section-head"><div><h2>Explora las oportunidades <span class="count-pill">${all.length}</span></h2><p>Información trazable, desde el origen hasta tu decisión.</p></div>${button(icon('download')+' 2. Exportar','export','Exporta los resultados filtrados como CSV a tu equipo. Solo lectura; no envía datos a terceros.','secondary compact')}</div><div class="data-tabs" role="group" aria-label="Origen de los datos">${button('2. Captación real','mode-real','Muestra únicamente las fichas captadas por fuentes web. Solo lectura.',mode==='real'?'tab active':'tab')}${button('2. Demo','mode-demo','Muestra ejemplos sintéticos en una vista separada. Solo lectura; no son ofertas reales.',mode==='demo'?'tab active':'tab')}${button('2. Carga complementaria','mode-manual','Muestra tus importaciones CSV o manuales guardadas en este navegador. Solo lectura.',mode==='manual'?'tab active':'tab')}</div>${mode==='demo'?'<div class="notice amber">DEMO — NO REAL. Estos inmuebles y cifras son sintéticos; no representan ofertas.</div>':''}<form id="filters" class="filter-bar"><label class="search-field">${icon('search')}<input type="search" name="query" aria-label="Buscar inmueble o distrito" placeholder="Buscar inmueble, distrito…" value="${e(filters.query||'')}"></label>${select('region','Ubicación',[['','Todas las regiones'],...new Set(all.map(o=>o.region||'Por verificar'))],filters.region)}${select('type','Inmueble',[['','Todos los tipos'],...TYPES],filters.type)}${select('risk','Riesgo',[['','Todos los riesgos'],...RISKS],filters.risk)}<details class="advanced"><summary>Más filtros <span>+</span></summary><div class="advanced-grid">${select('district','Distrito',[['','Todos'],...new Set(all.map(o=>materialize(o,state.settings).district))],filters.district)}${select('source','Origen',[['','Todos'],...new Set(all.map(o=>o.source))],filters.source)}${select('currency','Moneda del precio',[['','Todas'],['PEN','Soles (PEN)'],['USD','Dólares (USD)']],filters.currency)}${input('minPrice','Precio publicado mínimo',filters.minPrice)}${input('maxPrice','Precio publicado máximo',filters.maxPrice)}${input('maxCapital','Capital total máximo · USD',filters.maxCapital)}${input('minArea','Área mínima · m²',filters.minArea)}${input('minROI','ROI mínimo · %',filters.minROI)}${input('minDiscount','Descuento estimado mínimo · %',filters.minDiscount)}${input('maxMonths','Plazo máximo · meses',filters.maxMonths)}${select('occupancy','Ocupación',[['','Todas'],...OCCUPANCIES],filters.occupancy)}${input('capturedAfter','Captado desde',filters.capturedAfter,'date')}${input('updatedAfter','Consultado desde',filters.updatedAfter,'date')}${input('deadlineBefore','Fecha límite hasta',filters.deadlineBefore,'date')}<p class="hint wide">Precio: moneda original. Capital y ROI: escenario en USD. Los valores desconocidos no pasan un filtro numérico. Ningún filtro se aplica a la extracción.</p></div></details></form><div class="table-toolbar"><span id="result-count"></span><div>${button('2. Limpiar filtros','clear-filters','Elimina tus filtros de la vista para mostrar todos los registros. Solo lectura.','text-button')}<label>Ordenar por <select id="sort" aria-label="Ordenar resultados">${[['score','Score de inversión'],['roi','ROI proyectado'],['profit','Utilidad proyectada'],['price','Capital menor'],['new','Más recientes']].map(([v,l])=>`<option value="${v}" ${sort===v?'selected':''}>${l}</option>`).join('')}</select></label></div></div><div id="table"></div></section><div class="analysis-foot"><div>${icon('info')} El precio publicado no garantiza disponibilidad. Un score no sustituye la revisión legal.</div><span>${online?'Fuente conectada: SUNAT':'Backend local no conectado'}</span></div>`;
  renderTable();
  $('#filters').addEventListener('input',()=>{Object.assign(filters,Object.fromEntries(new FormData($('#filters'))));renderTable();});
  $('#filters').addEventListener('submit',ev=>ev.preventDefault());
  $('#sort').addEventListener('change',ev=>{sort=ev.target.value;renderTable();});
}
function renderTable(){
  const list=selected();$('#result-count').textContent=`${list.length} de ${items().length} oportunidades · sin límite de precio automático`;
  if(!list.length){$('#table').innerHTML=`<div class="empty">${icon('radar')}<h3>${items().length?'No hay coincidencias':'Tu radar está listo para empezar'}</h3><p>${items().length?'Ajusta los filtros para ampliar la búsqueda.':'Ejecuta una búsqueda en fuentes públicas o explora la demo separada.'}</p><a class="primary" href="#captar">1. Ir a captar oportunidades ${icon('arrow')}</a></div>`;return;}
  $('#table').innerHTML=`<div class="table-scroll"><table><thead><tr><th>INMUEBLE / UBICACIÓN</th><th>PRECIO PUBLICADO</th><th>CAPITAL TOTAL</th><th>ROI ESTIMADO</th><th>RIESGO</th><th>SCORE</th><th><span class="sr-only">Acciones</span></th></tr></thead><tbody>${list.map((raw,i)=>{const o=materialize(raw,state.settings),f=financials(raw,state.settings),score=scoreOpportunity(raw,state.settings);return `<tr><td><div class="property-cell"><span class="property-art art-${i%4}">${icon('building')}</span><div><strong>${e(o.title)}</strong><span>${e(o.district==='Por verificar'?o.region:o.district)} <b>·</b> ${e(o.type)} ${o.area?`<b>·</b> ${o.area} m²`:''}</span><small>${e(o.source)} ${o.demo?'· DEMO — NO REAL':''} ${state.saved.includes(o.id)?'· En seguimiento':''}</small></div></div></td><td><strong>${money(o.original_price??o.acquisition_price,o.currency)}</strong><small>${o.demo?'Precio simulado':'Base de remate · según fuente'}</small></td><td><strong>${money(f.total)}</strong><small>${f.ready?'Escenario · USD':'Faltan supuestos'}</small></td><td><strong class="${f.roi>0?'positive':''}">${pct(f.roi)}</strong><small>Antes de impuestos</small></td><td><span class="risk ${o.risk==='Bajo'?'low':o.risk==='Alto'?'high':'medium'}"><span></span>${e(o.risk)}</span></td><td>${score.value!==null?`<div class="score">${score.value}<small>/100</small></div>`:'<span class="pending">Pendiente</span>'}</td><td>${button('2. Ver '+icon('chevron'),'detail','Abre precio, evidencia y escenarios del inmueble. Solo lectura; los datos requieren verificación.','row-button',`data-id="${e(o.id)}"`)}</td></tr>`;}).join('')}</tbody></table></div><div class="table-bottom"><span>${list.length} resultados visibles</span><span>${mode==='demo'?'Datos de prueba aislados':'Consulta original disponible en cada ficha'} ${icon('shield')}</span></div>`;
}

function renderCapture(){
  const last=runs[0];
  $('#content').innerHTML=`<div class="capture-grid"><section class="panel"><div class="section-head"><div><div class="eyebrow">01 / CAPTACIÓN AUTOMÁTICA</div><h2>Conecta con las oportunidades</h2><p>Consulta fuentes públicas. Sin importar archivos ni introducir inmuebles.</p></div>${icon('radar','big-icon')}</div><form id="search-form"><div class="source-grid">${sources.length?sources.map(s=>`<label class="source-card ${s.enabled?'enabled':''}"><div class="source-card-top"><span class="source-logo">${e(s.name.slice(0,2))}</span><input type="checkbox" name="sources" value="${e(s.id)}" ${s.enabled?'checked':'disabled'} aria-label="Seleccionar ${e(s.name)}"></div><strong>${e(s.name)}</strong><small>${e(s.category)}</small><span class="source-status ${s.enabled?'on':''}">${s.enabled?'●':'○'} ${e(s.status)}</span><p>${e(s.reason)}</p>${s.url?`<a href="${e(s.url)}" target="_blank" rel="noopener noreferrer">Sitio oficial ↗</a>`:''}</label>`).join(''):'<div class="notice amber">El servicio local no está disponible. Inícialo para consultar las fuentes.</div>'}</div><div class="scan-options">${input('pages','Páginas por ejecución',1,'number','min="1" max="10" step="1" required')}${input('start_page','Empezar en página',last?.coverage?.next_page!=null?last.coverage.next_page+1:1,'number','min="1" max="1001" step="1" required')}<p>No hay filtro de precio. Se conserva cada inmueble encontrado en las páginas consultadas. Continúa desde la siguiente página para ampliar la cobertura.</p></div><div class="scan-approval"><label><input name="approval" type="checkbox" required> <span><b>2. Autorizar esta consulta</b><br>Leer las fuentes seleccionadas y guardar resultados públicos en la base de datos local.</span></label></div>${button(icon('search')+' 3. Buscar oportunidades','search','Ejecuta los conectores seleccionados, consulta páginas públicas y escribe fichas e historial en SQLite local. Requiere autorización de consulta; respeta robots, límite de páginas y 60 segundos entre ejecuciones.','primary',`type="submit" ${!online||last?.status==='running'?'disabled':''}`)}</form></section><aside class="capture-aside"><section class="panel process-panel"><div class="eyebrow">UN FLUJO TRAZABLE</div><h3>Del origen a la decisión.</h3><ol class="vertical-steps"><li><b>1</b><div>Selecciona las fuentes<small>Solo conectores habilitados.</small></div></li><li><b>2</b><div>Autoriza la consulta<small>Control explícito de escritura.</small></div></li><li><b>3</b><div>Ejecuta la búsqueda<small>Extracción y deduplicación.</small></div></li><li><b>4</b><div>Revisa los resultados<small>Datos, fechas y evidencia.</small></div></li></ol><div class="notice">${icon('shield')} Ninguna búsqueda presenta ofertas ni accede a portales privados.</div></section><section class="panel"><h3>Clasificación con IA</h3><span class="risk medium">Pendiente · Big Brain V2</span><p class="hint">El puente gobernado no estuvo disponible. La extracción estructurada funciona por separado. No se simulan resultados de IA.</p></section></aside></div><section class="panel run-panel"><div class="section-head"><div><div class="eyebrow">04 / RESULTADO Y EVIDENCIA</div><h2>Historial de captación</h2></div><a href="#analizar" class="text-link">Ver oportunidades ${icon('arrow')}</a></div><div id="run-history">${runHistory()}</div></section><details class="panel complementary"><summary>Herramientas complementarias <span>CSV y carga manual</span></summary><p class="hint">Solo respaldo y pruebas. Se guardan en este navegador, separados de las fuentes web.</p><div class="complement-grid"><form id="csv-form"><h3>Importar CSV</h3><label class="field"><span>Archivo CSV · máximo 2 MB</span><input id="csv-file" type="file" accept=".csv,text/csv"></label><label class="field"><span>O pega el contenido</span><textarea id="csv-text" rows="5" placeholder="title,district,type,…"></textarea></label>${button('1. Descargar plantilla','template','Descarga una fila sintética y las columnas del CSV. Escribe un archivo local; no consulta fuentes.','secondary')}${button('2. Revisar CSV','preview-csv','Valida el CSV y calcula duplicados antes de guardarlo. Solo lectura.','primary','type="submit"')}<div id="import-preview"></div></form><form id="manual-form"><h3>Añadir una ficha manual</h3><div class="form-grid">${input('title','Nombre del inmueble','','text','required maxlength="140"')}${input('district','Distrito','','text','required')}${select('type','Tipo',TYPES)}${input('acquisition_price','Precio de compra · USD','','number','required')}${input('exit_price','Valor de salida estimado · USD','','number','required')}${input('area','Área · m²','','number','required')}${input('months','Plazo · meses','','number','required max="120"')}${['closing_costs','renovation','holding_costs','selling_costs'].map((k,i)=>input(k,['Cierre · USD','Reforma · USD','Tenencia · USD','Venta · USD'][i],'','number','required')).join('')}${input('source_url','URL original','','url')}</div><label class="field"><span>Evidencia y fecha</span><textarea name="evidence" required maxlength="2000"></textarea></label>${button('3. Guardar ficha manual','manual-save','Valida y guarda una ficha complementaria en este navegador. Escritura local; no verifica los datos ni presenta ofertas.','primary','type="submit"')}</form></div></details>`;
  $('#search-form')?.addEventListener('submit',async ev=>{ev.preventDefault();const form=new FormData(ev.target);try{const run=await api('search',{sources:form.getAll('sources'),pages:Number(form.get('pages')),start_page:Number(form.get('start_page'))-1});runs.unshift(run);renderCapture();startPoll();toast('Consulta iniciada. Puedes seguir usando el radar.');}catch(err){toast(err.message);}});
  $('#csv-form').addEventListener('submit',previewCSV);
  $('#manual-form').addEventListener('submit',ev=>{ev.preventDefault();try{const o=validateOpportunity(Object.fromEntries(new FormData(ev.target)));const result=mergeOpportunities(localItems,[o]);localItems=result.items;saveLocal();toast('Ficha guardada en carga complementaria.');ev.target.reset();}catch(err){toast(err.message);}});
}
function runHistory(){return runs.length?runs.map(r=>`<div class="run-row"><span class="run-icon">${icon(r.status==='running'?'radar':r.status==='failed'?'info':'shield')}</span><div><strong>${e(r.source)} <span class="run-status">${e({running:'En ejecución',completed:'Completado',partial:'Parcial',failed:'Error',interrupted:'Interrumpido'}[r.status]||r.status)}</span></strong><small>${date(r.created_at)} · ${e(r.message)}</small>${r.coverage?`<small>${r.coverage.pages} página(s) consultada(s) · ${r.coverage.next_page!=null?`Continúa en página ${r.coverage.next_page+1}`:'Fin del catálogo'} · ${r.coverage.errors.length} error(es)</small>`:''}${r.coverage?.errors?.length?`<details><summary>Ver diagnóstico</summary><p class="hint">${r.coverage.errors.map(x=>`${e(x.id)}: ${e(x.error)}`).join('<br>')}</p></details>`:''}</div><div class="run-numbers"><b>${r.found||0}<small>captados</small></b><b>${r.counts?.new||0}<small>nuevos</small></b><b>${r.counts?.updated||0}<small>actualizados</small></b><b>${r.counts?.duplicate||0}<small>duplicados</small></b></div></div>`).join(''):'<div class="empty small">Todavía no hay ejecuciones. Selecciona una fuente y empieza a captar.</div>';}
function startPoll(){clearInterval(pollTimer);pollTimer=setInterval(async()=>{try{runs=await api('runs');if(view==='captar'&&$('#run-history'))$('#run-history').innerHTML=runHistory();if(!runs.some(r=>r.status==='running')){clearInterval(pollTimer);real=await api('opportunities');if(view==='captar')renderCapture();if(view==='analizar')renderAnalysis();toast('Captación finalizada. Revisa el historial y los inmuebles.');}}catch{clearInterval(pollTimer);toast('Se perdió la conexión. Consulta el historial al reconectar.');}},1500);}
async function previewCSV(ev){ev.preventDefault();try{let text=$('#csv-text').value;const f=$('#csv-file').files[0];if(f){if(f.size>2_000_000)throw new Error('Máximo 2 MB.');text=await f.text();}const rows=parseCSV(text);pendingImport=rows.map((r,i)=>{try{return validateOpportunity(r,'CSV')}catch(err){throw new Error(`Fila ${i+2}: ${err.message}`)}});const preview=mergeOpportunities(localItems,pendingImport,()=>`preview-${Math.random()}`);$('#import-preview').innerHTML=`<div class="notice">${rows.length} filas válidas · ${preview.counts.new} nuevas · ${preview.counts.updated} actualizadas · ${preview.counts.duplicate} duplicadas.</div>${button('3. Confirmar importación','confirm-import','Guarda las filas revisadas en la carga complementaria del navegador. Escritura local; conserva captación real por separado.','primary')}`;}catch(err){pendingImport=null;$('#import-preview').innerHTML=`<p class="error" role="alert">${e(err.message)}</p>`;}}

function renderDossiers(){
  const all=[...real,...DEMO,...localItems].filter(o=>state.saved.includes(o.id));
  $('#content').innerHTML=`<section class="panel"><div class="section-head"><div><h2>Tu mesa de evaluación</h2><p>Reúne la evidencia antes de tomar una decisión.</p></div><span class="count-pill">${all.length} expedientes</span></div>${all.length?`<div class="dossier-grid">${all.map(o=>`<article class="dossier"><div class="dossier-top">${icon('folder')}<span>${o.demo?'DEMO — NO REAL':e(o.source)}</span></div><h3>${e(o.title)}</h3><p>${e(o.district==='Por verificar'?o.region:o.district)} · ${money(o.original_price??o.acquisition_price,o.currency)}</p><span class="risk medium">Revisión pendiente</span><p class="hint">${e(state.notes[o.id]||'Añade notas y revisa la evidencia en la ficha.')}</p>${button('3. Revisar expediente '+icon('arrow'),'detail','Abre el expediente y sus notas. Solo lectura hasta guardar explícitamente un cambio.','secondary',`data-id="${e(o.id)}"`)}</article>`).join('')}</div>`:'<div class="empty">'+icon('folder')+'<h3>Construye tu lista de seguimiento</h3><p>Abre un inmueble en Analizar y guárdalo aquí.</p><a href="#analizar" class="primary">2. Explorar oportunidades</a></div>'}</section><div class="notice">4. La decisión de inversión se toma fuera de esta aplicación, con aprobación humana y revisión profesional.</div>`;
}
function renderSettings(){
  const s=state.settings;
  $('#content').innerHTML=`<form id="settings-form"><div class="settings-grid"><section class="panel"><div class="eyebrow">01 / ESTRATEGIA</div><h2>Tu capital, tus criterios.</h2><p class="hint">El presupuesto es una referencia. No excluye inmuebles durante la captación ni activa filtros automáticamente.</p>${input('budget','Presupuesto de referencia · USD',s.budget,'number','required')}${input('fx','Tipo de cambio supuesto · PEN por USD',s.fx||'','number','max="100" placeholder="Sin configurar"')}<p class="hint">Deja el cambio vacío para no convertir soles. No se consulta un tipo de cambio en vivo. La fuente conserva su precio y moneda originales.</p></section><section class="panel"><div class="eyebrow">02 / RANKING EXPLICABLE</div><h2>Pesos del score</h2><p class="hint">Deben sumar 100. La clasificación IA es independiente y está pendiente.</p>${Object.entries(s.weights).map(([k,v])=>`<label class="weight-row"><span>${{roi:'Rentabilidad',discount:'Descuento estimado',risk:'Riesgo',liquidity:'Liquidez',capital:'Capital y plazo'}[k]}</span><input name="${k}" type="number" min="0" max="100" value="${v}" required><b>%</b></label>`).join('')}<div class="weight-total">Total <b id="weight-total">100%</b></div></section><section class="panel"><div class="eyebrow">03 / SUPUESTOS FINANCIEROS</div><h2>Margen para la incertidumbre</h2>${input('contingency','Contingencia sobre compra + reforma · %',s.contingency,'number','max="100" required')}${input('tax','Tasa fiscal efectiva hipotética · %',s.tax,'number','max="100" required')}<p class="hint">El impuesto calculado es un supuesto sobre utilidad positiva, no una liquidación fiscal. Compra, gastos legales, financiación e impuestos de adquisición se detallan por inmueble. Consulta a un asesor para cada operación.</p></section><section class="panel"><div class="eyebrow">04 / ENTORNO Y DATOS</div><h2>Control local</h2><div class="settings-line"><span>Captación web</span><b>${online?'Servicio conectado':'Requiere backend'}</b></div><div class="settings-line"><span>Persistencia</span><b>${online?'SQLite local':'Navegador'}</b></div><div class="settings-line"><span>Clasificación IA</span><b>Pendiente · BBV2</b></div><div class="settings-line"><span>Usuarios y roles</span><b>Pendiente · producción</b></div><p class="hint">Este servicio es de un solo usuario y está limitado al equipo local. GitHub Pages alojará la interfaz; la captación privada necesita un servidor separado.</p>${button('4. Descargar respaldo','backup','Descarga fichas, parámetros y seguimiento como JSON a tu equipo. Solo lectura; el archivo puede contener tus notas y no debe publicarse.','secondary')}</section></div><div class="form-actions"><p id="settings-error" class="error" role="alert"></p>${button('4. Guardar configuración','settings-save','Guarda presupuesto, tipo de cambio supuesto, pesos e impuestos en SQLite local o navegador si no hay servicio. Recalcula escenarios; no cambia los precios publicados.','primary','type="submit"')}</div></form>`;
  $('#settings-form').addEventListener('input',()=>{$('#weight-total').textContent=Object.keys(s.weights).reduce((n,k)=>n+Number($(`[name="${k}"]`).value),0)+'%';});
  $('#settings-form').addEventListener('submit',async ev=>{ev.preventDefault();const data=Object.fromEntries(new FormData(ev.target));try{const next={weights:Object.fromEntries(Object.keys(s.weights).map(k=>[k,Number(data[k])])),tax:Number(data.tax),contingency:Number(data.contingency),budget:Number(data.budget),fx:Number(data.fx)};validateSettings(next);const prior=state.settings;state.settings=next;try{await persist()}catch(err){state.settings=prior;throw err;}shell();toast('Configuración guardada. La captación sigue sin límite de precio.');}catch(err){$('#settings-error').textContent=err.message;}});
}

function openDetail(id){
  const raw=[...real,...DEMO,...localItems].find(o=>o.id===id);if(!raw)return;activeId=id;
  const o=materialize(raw,state.settings),f=financials(raw,state.settings),sc=scoreOpportunity(raw,state.settings);
  const costs=[['Compra','acquisition_price'],['Gastos de cierre','closing_costs'],['Reforma','renovation'],['Tenencia','holding_costs'],['Comercialización','selling_costs'],['Gastos legales','legal_costs'],['Financiación','financing_costs'],['Impuestos de adquisición','acquisition_taxes']];
  $('#detail').innerHTML=`<div class="drawer-head"><div class="eyebrow">EXPEDIENTE / ${e(raw.id)}</div>${button('2. Cerrar '+icon('close'),'close-detail','Cierra el detalle y vuelve a la lista. Solo lectura.','text-button')}</div><div class="drawer-body"><span class="source-status on">${e(o.source)} ${o.demo?'· DEMO — NO REAL':'· FICHA CAPTADA'}</span><h2 id="detail-title">${e(o.title)}</h2><p class="hint">${e(o.region||o.district)} · ${e(o.type)} · ${o.area?o.area+' m²':'Área por verificar'}</p><div class="detail-price"><div><small>PRECIO ORIGINAL PUBLICADO</small><strong>${money(raw.original_price??raw.acquisition_price,raw.currency)}</strong></div><span class="risk medium">${e(o.risk)}</span></div>${raw.source_url?`<a href="${e(safeURL(raw.source_url))}" target="_blank" rel="noopener noreferrer" class="source-link">Ver ficha en la fuente original ↗</a>`:''}<div class="evidence-box"><b>Lo publicado ≠ lo verificado</b><p>${e(raw.evidence)}</p><dl><dt>Consultado</dt><dd>${date(raw.updated_at)}</dd><dt>Primera captura</dt><dd>${date(raw.captured_at)}</dd><dt>Fecha del portal</dt><dd>${date(raw.source_date)}</dd><dt>Límite del remate</dt><dd>${raw.deadline?date(raw.deadline):'Por verificar'}</dd><dt>Tasación publicada</dt><dd>${money(raw.original_appraisal,raw.currency)}</dd></dl>${raw.source_sha256?`<details><summary>Huella de la fuente</summary><code>${e(raw.source_sha256)}</code></details>`:''}</div><h3>Escenario de inversión <span>USD · estimaciones</span></h3>${raw.assessment_stale?'<div class="notice amber">La fuente cambió: revisa de nuevo los supuestos guardados.</div>':''}${!f.ready?'<div class="notice amber">Faltan datos para calcular rentabilidad. Completa un escenario; no usamos la tasación como valor de salida ni suponemos costes cero.</div>':''}<div class="financial-lines">${costs.map(([name,k])=>`<div><span>${name}</span><b>${money(o[k])}</b></div>`).join('')}<div><span>Contingencia · ${state.settings.contingency}%</span><b>${money(f.contingency)}</b></div><div class="total"><span>Capital total</span><b>${money(f.total)}</b></div></div><div class="scenario-grid">${[['conservative','Conservador','Salida −10%'],['base','Base','Salida definida'],['optimistic','Optimista','Salida +10%']].map(([key,label,desc])=>{const x=financials(raw,state.settings,key);return `<div class="scenario ${key==='base'?'base':''}"><small>${label}</small><strong>${pct(x.roi)}</strong><b>${money(x.profit)}</b><span>Utilidad antes de impuestos</span><small>${desc}</small></div>`;}).join('')}</div><p class="hint">Supuesto fiscal: ${state.settings.tax}%. Resultado después del supuesto: ${money(f.afterTaxEstimate)}. No equivale a ganancia neta fiscal ni a rentabilidad garantizada.</p><details class="estimate-editor"><summary>2. Editar supuestos y costes</summary><form id="assessment-form"><p class="hint">Todos los importes de este escenario están en USD. No se modifica el precio original. El valor de salida necesita comparables independientes; el score no valida esa evidencia.</p><div class="form-grid">${costs.map(([label,k])=>input(k,label+' · USD',o[k],'number','required')).join('')}${input('exit_price','Valor de salida estimado · USD',o.exit_price,'number','required')}${input('area','Área · m²',o.area,'number','required')}${input('months','Plazo · meses',o.months,'number','required max="120"')}${input('district','Distrito',o.district,'text','required')}${select('type','Tipo',TYPES,o.type)}${select('risk','Riesgo estimado',RISKS,o.risk)}${select('occupancy','Ocupación',OCCUPANCIES,o.occupancy)}</div><label class="field"><span>Justificación, comparables y fecha de los supuestos</span><textarea name="evidence" minlength="5" maxlength="2000" required>${e(raw.assessment?.evidence||'')}</textarea></label>${button('2. Guardar escenario','assessment-save','Guarda estimaciones en el expediente local. Escritura en SQLite; no altera valores publicados ni verifica aspectos legales.','primary','type="submit"')}<p class="error" id="assessment-error" role="alert"></p></form></details><h3>Por qué este score</h3>${sc.value===null?'<p class="hint">Pendiente: faltan costes, valoración, plazo, tipo o riesgo. No se asigna una puntuación ficticia.</p>':`<div class="score-breakdown">${Object.entries(sc.parts).map(([k,v])=>`<div><span>${{roi:'Rentabilidad',discount:'Descuento',risk:'Riesgo',liquidity:'Liquidez',capital:'Capital/plazo'}[k]}</span><meter min="0" max="100" value="${v}"></meter><b>${Math.round(v)} × ${state.settings.weights[k]}%</b></div>`).join('')}</div><p class="hint">ROI saturado al 30%; descuento al 25%; riesgo y liquidez por tablas; capital/plazo por penalización lineal. Metodología heurística, no IA.</p>`}<div class="notice amber">Etiqueta «recomendado» bloqueada: falta validación de titularidad, ocupación y comparables.</div><h3>3. Revisión crítica</h3><ul class="checklist">${CHECKS.map(c=>`<li>${icon('shield')}<span>${c}</span><small>Pendiente</small></li>`).join('')}</ul><p class="hint">No se interpreta «inscrito» como ausencia de cargas. La app no certifica el estado legal.</p><label class="field"><span>Notas del expediente</span><textarea id="dossier-note" maxlength="2000" placeholder="Próxima revisión, evidencias pendientes…">${e(state.notes[id]||'')}</textarea></label><div class="drawer-actions">${button((state.saved.includes(id)?'3. Quitar seguimiento':'3. Guardar en expedientes')+' '+icon('bookmark'),'save-watch','Añade o quita el inmueble de tu seguimiento local. Escritura en SQLite o navegador; no elimina la ficha ni presenta ofertas.','primary')}${button('3. Guardar notas','save-note','Guarda tus notas en el expediente local. No envía mensajes ni verifica su contenido.','secondary')}</div><p class="hint">4. Cualquier oferta o compra requiere tu aprobación fuera de esta aplicación.</p></div>`;
  $('#assessment-form').addEventListener('submit',async ev=>{ev.preventDefault();try{const data=Object.fromEntries(new FormData(ev.target));for(const k of [...costs.map(x=>x[1]),'exit_price','area','months'])data[k]=Number(data[k]);if(raw.source_id==='sunat'){await api(`opportunities/${encodeURIComponent(id)}/assessment`,data);real=await api('opportunities');}else{Object.assign(raw,{assessment:data});if(!raw.demo)saveLocal();}openDetail(id);if(view==='analizar')renderAnalysis();toast('Escenario guardado como estimación.');}catch(err){$('#assessment-error').textContent=err.message;}});
  if(!$('#detail').open)$('#detail').showModal();
}

document.addEventListener('click',async ev=>{
  const b=ev.target.closest('[data-action]');if(!b)return;
  const action=b.dataset.action;
  try{
    if(action==='detail')openDetail(b.dataset.id);
    if(action==='close-detail')$('#detail').close();
    if(action.startsWith('mode-')){mode=action.slice(5);Object.keys(filters).forEach(k=>delete filters[k]);renderAnalysis();}
    if(action==='clear-filters'){Object.keys(filters).forEach(k=>delete filters[k]);renderAnalysis();}
    if(action==='export'){download('paw-oportunidades.csv',csvExport(selected().map(o=>materialize(o,state.settings))));toast('Exportación descargada.');}
    if(action==='template'){download('paw-plantilla-demo.csv',csvExport([DEMO[0]]));}
    if(action==='confirm-import'&&pendingImport){const result=mergeOpportunities(localItems,pendingImport);localItems=result.items;saveLocal();pendingImport=null;$('#import-preview').innerHTML=`<div class="notice">4. Guardado: ${result.counts.new} nuevas, ${result.counts.updated} actualizadas, ${result.counts.duplicate} duplicadas. Ver Carga complementaria en Analizar.</div>`;toast('Importación complementaria completada.');}
    if(action==='backup')download('paw-respaldo-privado.json',JSON.stringify({schema:1,exported_at:new Date().toISOString(),state,opportunities:real,localItems,runs},null,2),'application/json');
    if(action==='save-watch'){const prior=[...state.saved];state.saved=state.saved.includes(activeId)?state.saved.filter(x=>x!==activeId):[...state.saved,activeId];try{await persist()}catch(err){state.saved=prior;throw err}openDetail(activeId);shell();toast('Seguimiento actualizado.');}
    if(action==='save-note'){const old=state.notes[activeId];state.notes[activeId]=$('#dossier-note').value;try{await persist()}catch(err){state.notes[activeId]=old;throw err}toast('Notas guardadas.');}
  }catch(err){toast(err.message);}
});
function navigate(){const requested=location.hash.slice(1);view=['captar','analizar','expedientes','configuracion'].includes(requested)?requested:'analizar';shell();window.scrollTo({top:0});}
window.addEventListener('hashchange',navigate);
async function init(){
  $('#app').innerHTML='<div class="loading"><img src="./assets/mark.svg" width="56" alt="PAW"><h1>Preparando tu radar</h1><p>Conectando con la base de datos local…</p></div>';
  try{const session=await api('session');token=session.token||'';const health=await api('health');backendStorage=health.storage==='postgres'?'Supabase PostgreSQL':(health.storage||'desconocida');online=true;[real,sources,runs]=await Promise.all([api('opportunities'),api('sources'),api('runs')]);const saved=await api('state');if(saved){validateSettings(saved.settings);state=saved;}}
  catch{online=false;try{const saved=JSON.parse(localStorage.getItem('paw-settings-v1')||'null');if(saved){validateSettings(saved.settings);state=saved;}}catch{}}
  navigate();if(runs.some(r=>r.status==='running'))startPoll();
}
init();
